using System;using System.IO;using System.Collections.Generic;using System.Security.AccessControl;using System.Security.Principal;using Microsoft.Win32;
// Read-only existing legacy-binding authority. Cannot capture or replace a baseline.
internal sealed class UsbExactBlockBaseline:IDisposable {
 readonly List<IDisposable> pins=new List<IDisposable>();UsbLegacyReleasedBaseline.Lease lease;bool disposed;
 internal string Nonce{get{Check();return lease.Nonce;}}
 static readonly string StateRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SentinelUsbAdmission","State");
 static void Security(FileSystemSecurity acl,bool leaf){string owner=acl.GetOwner(typeof(SecurityIdentifier)).Value;if(owner!="S-1-5-18"&&owner!="S-1-5-32-544"&&owner!="S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464")throw new InvalidOperationException("Legacy binding owner refused");if(leaf&&!acl.AreAccessRulesProtected)throw new InvalidOperationException("Legacy binding ACL refused");foreach(FileSystemAccessRule rule in acl.GetAccessRules(true,true,typeof(SecurityIdentifier))){string sid=rule.IdentityReference.Value;if(rule.AccessControlType!=AccessControlType.Allow||sid=="S-1-5-18"||sid=="S-1-5-32-544"||(rule.PropagationFlags&PropagationFlags.InheritOnly)!=0)continue;if(leaf||(rule.FileSystemRights&(FileSystemRights.Delete|FileSystemRights.DeleteSubdirectoriesAndFiles|FileSystemRights.ChangePermissions|FileSystemRights.TakeOwnership))!=0)throw new InvalidOperationException("Legacy binding writable");}}
 internal UsbExactBlockBaseline(Action<RegistryKey> validateProtectedOverlay){if(validateProtectedOverlay==null)throw new ArgumentNullException("validateProtectedOverlay");try{var ancestry=new List<string>();for(var cursor=new DirectoryInfo(StateRoot);cursor!=null;cursor=cursor.Parent)ancestry.Insert(0,cursor.FullName);foreach(string path in ancestry){pins.Add(new SentinelPolicyDirectory(path));Security(Directory.GetAccessControl(path),path==StateRoot);}string file=Path.Combine(StateRoot,"legacy-baseline.bin");if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Legacy binding reparse refused");var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read);pins.Add(stream);Security(stream.GetAccessControl(),true);if(stream.Length!=104)throw new InvalidOperationException("Legacy binding length refused");byte[] bytes=new byte[104];int offset=0;while(offset<bytes.Length){int n=stream.Read(bytes,offset,bytes.Length-offset);if(n<1)throw new IOException();offset+=n;}lease=UsbLegacyReleasedBaseline.AcquireForExactOverlay(bytes,validateProtectedOverlay);}catch{Dispose();throw;}}
 internal void Check(){if(disposed||lease==null)throw new InvalidOperationException("Legacy binding unavailable");lease.Check();}
 public void Dispose(){if(disposed)return;disposed=true;if(lease!=null)lease.Dispose();for(int i=pins.Count-1;i>=0;i--)pins[i].Dispose();}
}
